// ----- Helpers -----
function rand(min, max) { return Math.random() * (max - min) + min; }

// ----- Starfield background -----
const stars = [];
for (let i = 0; i < 100; i++) {
  stars.push({ x: rand(0, canvas.width), y: rand(0, canvas.height), r: rand(0.5, 1.5) });
}
function drawStars() {
  ctx.fillStyle = '#222';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = '#fff';
  for (const s of stars) {
    ctx.beginPath();
    ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2);
    ctx.fill();
  }
}

// ----- Player ship -----
const ship = {
  x: canvas.width / 2,
  y: canvas.height / 2,
  r: 12,
  speed: 2,
  fuel: 100,
  dx: 0,
  dy: 0,
};

function drawShip() {
  const angle = Math.atan2(ship.dy, ship.dx) || 0;
  ctx.save();
  ctx.translate(ship.x, ship.y);
  ctx.rotate(angle);
  // ship body – triangle
  ctx.fillStyle = gameOver ? '#777' : '#0ff';
  ctx.beginPath();
  ctx.moveTo(0, -ship.r);
  ctx.lineTo(ship.r, ship.r);
  ctx.lineTo(-ship.r, ship.r);
  ctx.closePath();
  ctx.fill();
  // thrust flame
  if (ship.dx || ship.dy) {
    ctx.fillStyle = '#ff8';
    ctx.beginPath();
    ctx.moveTo(0, ship.r);
    ctx.lineTo(4, ship.r + 8);
    ctx.lineTo(-4, ship.r + 8);
    ctx.closePath();
    ctx.fill();
  }
  ctx.restore();
}

// ----- Input handling -----
const keys = {};
window.addEventListener('keydown', e => { keys[e.key] = true; });
window.addEventListener('keyup', e => { keys[e.key] = false; });

function updateShip() {
  let ax = 0, ay = 0;
  if (keys['ArrowLeft'] || keys['a']) ax -= 1;
  if (keys['ArrowRight'] || keys['d']) ax += 1;
  if (keys['ArrowUp'] || keys['w']) ay -= 1;
  if (keys['ArrowDown'] || keys['s']) ay += 1;
  if (ax || ay) {
    const len = Math.hypot(ax, ay);
    ax /= len; ay /= len;
    ship.dx = ax * ship.speed;
    ship.dy = ay * ship.speed;
    ship.fuel = Math.max(0, ship.fuel - 0.05);
  } else {
    ship.dx = ship.dy = 0;
  }
  ship.x = Math.max(ship.r, Math.min(canvas.width - ship.r, ship.x + ship.dx));
  ship.y = Math.max(ship.r, Math.min(canvas.height - canvas.height - ship.r, ship.y + ship.dy));
}

