  ctx.fillStyle = '#222';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = '#fff';
  for (const s of stars) {
    ctx.beginPath();
    ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2);
    ctx.fill();
  }
}

// ----- Player ship -----
const ship = {
  x: canvas.width / 2,
  y: canvas.height / 2,
  r: 12,
  speed: 2,
  fuel: 100,
  dx: 0,
  dy: 0,
};

function drawShip() {
  const angle = Math.atan2(ship.dy, ship.dx) || 0;
  ctx.save();
  ctx.translate(ship.x, ship.y);
  ctx.rotate(angle);
  // ship body – triangle
  ctx.fillStyle = gameOver ? '#777' : '#0ff';
  ctx.beginPath();
  ctx.moveTo(0, -ship.r);
  ctx.lineTo(ship.r, ship.r);
  ctx.lineTo(-ship.r, ship.r);
  ctx.closePath();
  ctx.fill();
  // thrust flame
  if (ship.dx || ship.dy) {
    ctx.fillStyle = '#ff8';
    ctx.beginPath();
    ctx.moveTo(0, ship.r);
    ctx.lineTo(4, ship.r + 8);
    ctx.lineTo(-4, ship.r + 8);
    ctx.closePath();
    ctx.fill();
    // thrust sound
    playTone(200, 0.05);
  }
  ctx.restore();
}

